package org.example.behavioral_pattern.observer_pattern.spring_boot;import org.springframework.context.event.EventListener;import org.springframework.stereotype.Component;@Componentpublic class DataWarehouseSyncService {    @EventListener    public void syncToWarehouse(OrderCreatedEvent event) {        System.out.println("📊 Gửi dữ liệu sang hệ thống phân tích cho đơn hàng: " + event.getOrder().getId());    }}